const input = $input.all()[0]?.json || {};
const niche = input.niche || '';
return [{ json: { niche } }];

const niche = $('Unpack Input').first().json.niche;
const shopRaw = $('Google Shopping Stickers').first()?.json || {};
const rbRaw   = (() => { try { return $('Redbubble Stickers').first()?.json || {}; } catch(_) { return {}; } })();

// Extract style signals from sticker titles/descriptions — NOT copying designs
// We only extract: color words, style descriptors, typography hints, theme keywords
const colorWords = /\b(black|white|red|blue|green|yellow|pink|purple|orange|gold|silver|neon|pastel|vintage|retro|dark|light|minimal|bold|bright|muted|earthy|rainbow)\b/gi;
const styleWords = /\b(minimalist|vintage|retro|bold|cute|funny|aesthetic|cottagecore|y2k|vaporwave|grunge|gothic|kawaii|anime|boho|floral|geometric|abstract|hand-drawn|watercolor|cartoon|flat|outline|line art|sketch|typographic|lettering)\b/gi;
const iconWords  = /\b(skull|heart|star|moon|sun|flower|leaf|wave|mountain|cat|dog|mushroom|ghost|lightning|crown|diamond|butterfly|bee|plant|tree|coffee|pizza|space|planet|alien|rainbow|cloud|fire|peace|yin yang)\b/gi;

const extractTerms = (text, regex) => [...new Set((text.match(regex) || []).map(s => s.toLowerCase()))];

const allTitles = [
  ...(shopRaw?.shopping_results || []).map(r => r.title + ' ' + (r.snippet || '')),
  ...(rbRaw?.organic_results    || []).filter(r => r.link?.includes('redbubble')).map(r => r.title + ' ' + (r.snippet || ''))
].join(' ');

const colors     = extractTerms(allTitles, colorWords).slice(0, 12);
const styles     = extractTerms(allTitles, styleWords).slice(0, 10);
const iconThemes = extractTerms(allTitles, iconWords).slice(0, 10);

// Extract price range signals (popular price points = validated demand)
const prices = (shopRaw?.shopping_results || [])
  .map(r => parseFloat((r.price || '').replace(/[^0-9.]/g, '')))
  .filter(p => p > 0);
const avgPrice  = prices.length ? (prices.reduce((s,p) => s+p, 0) / prices.length).toFixed(2) : null;

// Top sticker titles as inspiration seeds (public metadata — not design IP)
const inspirationSeeds = [
  ...(shopRaw?.shopping_results || []).slice(0, 8).map(r => r.title),
  ...(rbRaw?.organic_results    || []).slice(0, 5).map(r => r.title)
].filter(Boolean).slice(0, 10);

return [{ json: {
  source: 'stickers',
  niche,
  data: {
    colors,
    styles,
    iconThemes,
    inspirationSeeds,
    avgStickerPrice: avgPrice,
    totalResults: (shopRaw?.shopping_results || []).length + (rbRaw?.organic_results || []).length,
    legalNote: 'Style signals extracted from public metadata only — no design copying'
  }
} }];

const signals = $('Parse Sticker Signals').first()?.json || {};
const raw = $input.first().json?.choices?.[0]?.message?.content || '[]';
const clean = raw.replace(/```json|```/g, '').trim();
const match = clean.match(/\[[\s\S]*\]/);
let concepts = [];
try { concepts = JSON.parse(match?.[0] || '[]'); } catch(_) {}

return [{ json: {
  source: 'stickers',
  niche: signals.niche || '',
  data: {
    colors:            (signals.data?.colors || []),
    styles:            (signals.data?.styles || []),
    iconThemes:        (signals.data?.iconThemes || []),
    inspirationSeeds:  (signals.data?.inspirationSeeds || []),
    avgStickerPrice:   signals.data?.avgStickerPrice || null,
    totalResults:      signals.data?.totalResults || 0,
    originalConcepts:  concepts,
    legalNote: 'Style signals from public metadata only'
  }
} }];
